do $$ declare r record; begin for r in select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('business_create_campaign','business_create_contest','business_create_custom_qr','business_create_event','business_create_promotion','business_create_promotion_canonical','business_create_qr','business_delete_campaign','business_delete_contest','business_delete_event','business_delete_promotion','business_delete_qr','business_manage_campaign','business_manage_contest','business_manage_event','business_manage_promotion','business_manage_qr','business_update_campaign','business_update_contest','business_update_event','business_update_promotion','business_update_custom_qr','business_set_promotion_active','business_set_promotion_active_canonical','business_set_qr_active','business_update_custom_qr') loop execute format('revoke execute on function %I.%I(%s) from anon',r.nspname,r.proname,r.args); execute format('grant execute on function %I.%I(%s) to authenticated',r.nspname,r.proname,r.args); end loop; end $$;
